-- HQ decision integration: registered policy validation and honest propagation state.
begin;
create or replace function public.hq_lock_decision(p_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare d public.hq_decisions%rowtype;v int;p text;begin perform public.hq_assert_owner();select * into d from public.hq_decisions where id=p_id for update;if d.status<>'approved' then raise exception 'Decision must be approved before locking';end if;if d.rule_key is not null then foreach p in array d.affected_products loop perform public.hq_validate_policy_value(d.rule_key,p,d.rule_value);end loop;end if;update public.hq_decisions set status=case when effective_at is null or effective_at<=now() then 'active' else 'locked' end,locked_by=auth.uid(),locked_at=now(),updated_at=now() where id=p_id returning * into d;select coalesce(max(version),0)+1 into v from public.hq_decision_versions where decision_id=p_id;insert into public.hq_decision_versions(decision_id,version,snapshot,changed_by) values(p_id,v,to_jsonb(d),auth.uid());foreach p in array d.affected_products loop insert into public.hq_propagation_targets(decision_id,product_key,expected_config_key,expected_value,status) values(p_id,p,d.rule_key,d.rule_value,'pending') on conflict(decision_id,product_key,expected_config_key) do update set expected_value=excluded.expected_value,status='pending',error=null,verified_at=null;if d.rule_key is not null then update public.hq_product_configs set active=false,updated_at=now() where product_key=p and config_key=d.rule_key and active=true;insert into public.hq_product_configs(product_key,config_key,config_value,source_decision_id,source_version,effective_at,active,is_secret) values(p,d.rule_key,d.rule_value,p_id,v,coalesce(d.effective_at,now()),true,false);else update public.hq_propagation_targets set status='not_applicable',verified_at=now() where decision_id=p_id and product_key=p;end if;end loop;if d.rule_key is not null then perform public.hq_publish_policy_state(p_id);end if;if d.supersedes_id is not null then update public.hq_decisions set status='superseded',updated_at=now() where id=d.supersedes_id and status in('active','locked');insert into public.hq_decision_audit(decision_id,action,actor_id,details) values(d.supersedes_id,'superseded',auth.uid(),jsonb_build_object('replacement',p_id));end if;insert into public.hq_decision_audit(decision_id,action,actor_id,details) values(p_id,'locked',auth.uid(),jsonb_build_object('version',v,'authority_contract',true));insert into public.hq_notifications(category,severity,title,body,route,status,metadata) values('decision','success','Decision published',d.code||' · '||d.title,'/hq/decisions','unread',jsonb_build_object('decision_id',p_id,'products',d.affected_products,'state','published'));end $$;

create or replace function public.hq_verify_decision_propagation(p_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare r record;s hq_product_policy_state%rowtype;drift_count int:=0;verified_count int:=0;pending_count int:=0;begin perform public.hq_assert_owner();for r in select * from hq_propagation_targets where decision_id=p_id loop if r.expected_config_key is null then continue;end if;select * into s from hq_product_policy_state where product_key=r.product_key and policy_key=r.expected_config_key;if not found or s.state not in('verified','drift') then update hq_propagation_targets set status='pending',error='Awaiting independent observed-state verification',verified_at=null where id=r.id;pending_count:=pending_count+1;elsif s.state='verified' and s.observed_value is not distinct from r.expected_value then update hq_propagation_targets set status='applied',verified_at=now(),error=null where id=r.id;verified_count:=verified_count+1;else update hq_propagation_targets set status='drift',verified_at=now(),error='Observed product behavior does not match locked decision' where id=r.id;drift_count:=drift_count+1;end if;end loop;return jsonb_build_object('applied',verified_count,'drift',drift_count,'pending',pending_count);end $$;
revoke all on function public.hq_lock_decision(uuid),public.hq_verify_decision_propagation(uuid) from public,anon;grant execute on function public.hq_lock_decision(uuid),public.hq_verify_decision_propagation(uuid) to authenticated;
commit;